app.post('/api/narrative/script/scene-list/reorder', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const script = ensureScript(projectData);
    const { orderedIds } = req.body || {};
    if (!Array.isArray(orderedIds)) return res.status(400).json({ error: 'orderedIds (array) required' });
    const map = new Map((script.sceneList || []).map((e) => [e.id, e]));
    const reordered = orderedIds.map((id: string) => map.get(id)).filter(Boolean) as any[];
    reordered.forEach((e: any, i: number) => { e.number = i + 1; });
    script.sceneList = reordered;
    script.updatedAt = Date.now();
    saveProjectData(projectId, projectData);
    res.json({ success: true, script });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.delete('/api/narrative/script/scene-list/:id', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const script = ensureScript(projectData);
    const list = script.sceneList || [];
    const idx = list.findIndex((e) => e.id === req.params.id);
    if (idx < 0) return res.status(404).json({ error: 'Scene-list entry not found' });
    list.splice(idx, 1);
    list.forEach((e, i) => { e.number = i + 1; });
    script.updatedAt = Date.now();
    saveProjectData(projectId, projectData);
    res.json({ success: true, script });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Promote a scene-list entry to a production Scene. Snapshots the entry's
 * pitch as the new Scene's prose; records sceneId on the entry so resync
 * works later. The new Scene is appended to projectData.interactions.
 */
app.post('/api/narrative/script/scene-list/:id/promote', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const script = ensureScript(projectData);
    const list = script.sceneList || [];
    const entry = list.find((e) => e.id === req.params.id);
    if (!entry) return res.status(404).json({ error: 'Scene-list entry not found' });
    if (entry.linkedSceneId) {
      // Already promoted — return the existing scene
      const existing = projectData.interactions.find((s: any) => s.id === entry.linkedSceneId);
      if (existing) return res.json({ success: true, scene: existing, entry, alreadyPromoted: true });
    }

    const { title } = req.body || {};
    const newScene: any = {
      id: mintId('scene'),
      title: title || `Scene ${entry.number}`,
      prose: entry.pitch,
      description: entry.pitch,
      status: 'draft',
      participantIds: [],
      frames: [],
      position: projectData.interactions.length,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      sourceScriptSceneId: entry.id,
    };
    projectData.interactions.push(newScene);
    if (!(newScene as any).productionId) (newScene as any).productionId = activeProductionStamp(projectData);
    entry.linkedSceneId = newScene.id;
    entry.lastResyncedAt = Date.now();
    script.updatedAt = Date.now();
    saveProjectData(projectId, projectData);
    res.json({ success: true, scene: newScene, entry });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Resync a scene-list entry's pitch from its linked production Scene.
 * Pulls the Scene's prose back as the new pitch. Useful when the Scene
 * has been edited and the script should reflect the production state.
 */
app.post('/api/narrative/script/scene-list/:id/resync', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const script = ensureScript(projectData);
    const list = script.sceneList || [];
    const entry = list.find((e) => e.id === req.params.id);
    if (!entry) return res.status(404).json({ error: 'Scene-list entry not found' });
    if (!entry.linkedSceneId) return res.status(400).json({ error: 'Entry is not linked to a production Scene' });
    const scene = projectData.interactions.find((s: any) => s.id === entry.linkedSceneId);
    if (!scene) return res.status(404).json({ error: 'Linked scene not found' });
    entry.pitch = scene.prose || scene.description || entry.pitch;
    entry.lastResyncedAt = Date.now();
    script.updatedAt = Date.now();
    saveProjectData(projectId, projectData);
    res.json({ success: true, entry, script });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// ============================================================================
// ACTS ENDPOINTS — top-level story arcs that group scenes. New in stage 2
// of the pipeline restructure. Acts are the master organizing unit for the
// Storyboard phase. Scenes link to acts via `scene.actId`.
// ============================================================================

const ensureActs = (projectData: ProjectData): any[] => {
  if (!Array.isArray((projectData as any).acts)) (projectData as any).acts = [];
  return (projectData as any).acts!;
};

/**
 * List all acts for the project, sorted by order ascending.
 */
app.get('/api/narrative/acts', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    ensureActs(projectData);
    // T0a: scoped to the requested/active production, mirroring GET /interactions
    const acts = actsFor(projectData, req.query.productionId as string | undefined)
      .slice().sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0));
    res.json({ acts, total: acts.length });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Create a new act. Body: { title, arc?, order? }. If order is omitted, the
 * act is appended to the end.
 */
app.post('/api/narrative/acts', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const acts = ensureActs(projectData);
    const { title, arc, order } = req.body || {};
    if (!title || typeof title !== 'string') return res.status(400).json({ error: 'title is required' });
    const now = new Date().toISOString();
    const scopedActs = actsFor(projectData);
    const nextOrder = typeof order === 'number'
      ? order
      : (scopedActs.length === 0 ? 0 : Math.max(...scopedActs.map((a: any) => a.order ?? 0)) + 1);
    const act: any = {
      id: mintId('act'),
      productionId: activeProductionStamp(projectData),
      title,
      arc: arc || '',
      order: nextOrder,
      createdAt: now,
      updatedAt: now,
    };
    acts.push(act);
    saveProjectData(projectId, projectData);
    res.json({ success: true, act });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Update an act's fields. Body: { title?, arc?, order? }. Only provided
 * fields are patched.
 */
app.patch('/api/narrative/acts/:id', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const acts = ensureActs(projectData);
    const act = acts.find((a: any) => a.id === req.params.id);
    if (!act) return res.status(404).json({ error: 'Act not found' });
    const { title, arc, order } = req.body || {};
    if (title !== undefined) act.title = title;
    if (arc !== undefined) act.arc = arc;
    if (order !== undefined) act.order = order;
    act.updatedAt = new Date().toISOString();
    saveProjectData(projectId, projectData);
    res.json({ success: true, act });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Delete an act. Scenes linked via actId are unassigned (actId cleared),
 * not deleted.
 */
app.delete('/api/narrative/acts/:id', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const acts = ensureActs(projectData);
    const idx = acts.findIndex((a: any) => a.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Act not found' });
    acts.splice(idx, 1);
    // Unassign any scene that linked to this act
    let unassigned = 0;
    for (const scene of (projectData.interactions || [])) {
      if ((scene as any).actId === req.params.id) {
        (scene as any).actId = null;
        unassigned++;
      }
    }
    saveProjectData(projectId, projectData);
    res.json({ success: true, unassignedScenes: unassigned });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Reorder acts. Body: { orderedIds: string[] }. Each act's order is set to
 * its index in the array.
 */
app.post('/api/narrative/acts/reorder', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const acts = ensureActs(projectData);
    const orderedIds: string[] = req.body?.orderedIds || [];
    if (!Array.isArray(orderedIds) || orderedIds.length === 0) {
      return res.status(400).json({ error: 'orderedIds (string[]) is required' });
    }
    const now = new Date().toISOString();
    let updated = 0;
    orderedIds.forEach((id, i) => {
      const act = acts.find((a: any) => a.id === id);
      if (act) {
        act.order = i;
        act.updatedAt = now;
        updated++;
      }
    });
    saveProjectData(projectId, projectData);
    res.json({ success: true, updated, acts: acts.slice().sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0)) });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// ============================================================================
// TIMELINE ENDPOINTS — the editing-line for the Production phase. Each
// project has one timeline; tracks contain ordered clips; each clip
// references a shot (SceneFrame) by id. Stage 3 of the pipeline restructure.
// ============================================================================

// T0a: delegates to timelineFor — the ACTIVE production's timeline by default.
const ensureTimeline = (projectData: ProjectData, productionId?: string): any => {
  const timeline = timelineFor(projectData, productionId) as any;
  if (!Array.isArray(timeline.tracks)) timeline.tracks = [];
  if (!Array.isArray(timeline.items)) timeline.items = [];
  return timeline;
};

// Default video track id used by auto-populate and initial track creation.
const DEFAULT_VIDEO_TRACK_NAME = 'Main';

const ensureDefaultTrack = (timeline: any): any => {
  let track = timeline.tracks.find((t: any) => t.kind === 'video');
  if (track) return track;
  track = {
    id: mintId('track'),
    name: DEFAULT_VIDEO_TRACK_NAME,
    kind: 'video',
    order: 0,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  timeline.tracks.push(track);
  return track;
};

/**
 * Get the full timeline. Tracks + items, both sorted.
 */
app.get('/api/narrative/timeline', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const timeline = ensureTimeline(projectData);
    const tracks = timeline.tracks.slice().sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0));
    const items = timeline.items.slice().sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0));
    res.json({ timeline: { ...timeline, tracks, items } });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * Create a new track. Body: { name?, kind? (defaults 'video') }.
 */
// ============================================================================
// T0a-WORLD: PRODUCTIONS + ARCS REST (shared cores with the agent tools —
// the tools self-fetch these endpoints, house convention)
// ============================================================================

app.get('/api/narrative/productions', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const def = ensureDefaultProduction(projectData);
    res.json({
      productions: projectData.productions,
      activeProductionId: projectData.activeProductionId || def.id,
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.post('/api/narrative/productions', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), title, format } = req.body || {};
    if (!title || typeof title !== 'string') return res.status(400).json({ error: 'title is required' });
    const fmt = ['film', 'comic', 'episode'].includes(format) ? format : 'film';
    const projectData = loadProjectData(projectId);
    ensureDefaultProduction(projectData);
    const production: ProjectProduction = {
      id: mintId('prod'),
      title,
      format: fmt,
      createdAt: new Date().toISOString(),
    };
    projectData.productions!.push(production);
    saveProjectData(projectId, projectData);
    res.json({ success: true, production });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.post('/api/narrative/productions/:id/activate', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.params.id); // throws on unknown
    projectData.activeProductionId = production.id;
    saveProjectData(projectId, projectData);
    res.json({ success: true, activeProductionId: production.id });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

app.patch('/api/narrative/productions/:id', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), title, format, arcIds, autonomy, autonomyBudget } = req.body || {};
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.params.id);
    if (typeof title === 'string' && title) production.title = title;
    if (['film', 'comic', 'episode'].includes(format)) production.format = format;
    if (Array.isArray(arcIds)) production.arcIds = arcIds.map(String);
    // The Autonomy Dial (stored now; ENFORCED by hooks/scheduler at T3)
    if (['direct', 'review', 'autonomous'].includes(autonomy)) production.autonomy = autonomy;
    if (typeof autonomyBudget === 'number' && autonomyBudget >= 0) production.autonomyBudget = autonomyBudget;
    production.updatedAt = new Date().toISOString();
    saveProjectData(projectId, projectData);
    res.json({ success: true, production });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

app.delete('/api/narrative/productions/:id', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    if (req.params.id === DEFAULT_PRODUCTION_ID) {
      return res.status(400).json({ error: 'The default production cannot be deleted.' });
    }
    const production = getProduction(projectData, req.params.id); // throws on unknown
    // NON-DESTRUCTIVE: scenes/acts move to the default production rather
    // than being deleted (nothing generated is ever lost). The production's
    // own script/timeline go with the record — its CLIPS reference shots
    // that live on the scenes, so no media is lost either.
    let movedScenes = 0;
    for (const scene of projectData.interactions || []) {
      if (scene.productionId === production.id) { scene.productionId = DEFAULT_PRODUCTION_ID; movedScenes++; }
    }
    let movedActs = 0;
    for (const act of projectData.acts || []) {
      if ((act as any).productionId === production.id) { (act as any).productionId = DEFAULT_PRODUCTION_ID; movedActs++; }
    }
    projectData.productions = (projectData.productions || []).filter(p => p.id !== production.id);
    if (projectData.activeProductionId === production.id) projectData.activeProductionId = DEFAULT_PRODUCTION_ID;
    for (const arc of projectData.arcs || []) {
      arc.productionIds = (arc.productionIds || []).filter(id => id !== production.id);
    }
    saveProjectData(projectId, projectData);
    res.json({ success: true, deleted: production.id, movedScenes, movedActs, activeProductionId: projectData.activeProductionId });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

/**
 * T0b: the nit ledger — the Canon rail's data source. Summaries by default
 * (op counts by type); ?full=1 includes the operation payloads of the last
 * `limit` commits.
 */
app.get('/api/narrative/nit/log', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const ledger = loadNitLedger(projectId);
    const limit = Math.max(1, Math.min(100, Number(req.query.limit) || 20));
    const full = req.query.full === '1';
    const commits = (ledger.commits || []).slice(-limit).reverse().map((c: any) => {
      const opCounts: Record<string, number> = {};
      for (const op of c.operations || []) opCounts[op.type] = (opCounts[op.type] || 0) + 1;
      return {
        hash: c.hash,
        parentHashes: c.parentHashes,
        author: c.author,
        timestamp: c.timestamp,
        message: c.message,
        branch: c.branch,
        tags: c.tags,
        operationCount: (c.operations || []).length,
        opCounts,
        ...(full ? { operations: c.operations } : {}),
      };
    });
    const branches = Object.fromEntries(Object.entries(ledger.branches).map(([b, v]) => [b, v.headHash]));
    res.json({ branches, total: (ledger.commits || []).length, commits });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// ============================================================================
// C1 — WORLD EVENTS (CHRONICLE_DESIGN.md): the universe chronology.
// Media-agnostic happenings; scenes dramatize them via eventLinks (with
// provenance for staleness); a shared eventId across productions is the
// true-transmedia link. Blob-only until C1.5 hashes them into the ledger.
// ============================================================================

function ensureEvents(projectData: ProjectData): WorldEvent[] {
  if (!projectData.events) projectData.events = [];
  return projectData.events;
}

/** Default chronology = arrival order ("the log is the chronology until you
 *  say otherwise"). */
function nextChronologyIndex(projectData: ProjectData): number {
  const events = projectData.events || [];
  return events.length === 0 ? 0 : Math.max(...events.map(e => e.chronologyIndex ?? 0)) + 1;
}

/** Link a scene to an event WITH provenance (the snapshot+resync baseline). */
function linkSceneToEvent(scene: any, event: WorldEvent): void {
  if (!Array.isArray(scene.eventLinks)) scene.eventLinks = [];
  const existing = scene.eventLinks.find((l: any) => l.eventId === event.id);
  if (existing) existing.dramatizedAtEventUpdatedAt = event.updatedAt;
  else scene.eventLinks.push({ eventId: event.id, dramatizedAtEventUpdatedAt: event.updatedAt });
}

/** Every dramatization of an event across the world's productions: scenes
 *  that link it, plus comic pages whose scene links it. The Chronicle's
 *  click-through data. */
function getEventCoverage(projectData: ProjectData, eventId: string) {
  const scenes = (projectData.interactions || []).filter((s: any) =>
    (s.eventLinks || []).some((l: any) => l.eventId === eventId));
  const event = (projectData.events || []).find(e => e.id === eventId);
  const dramatizations = scenes.map((s: any) => {
    // Defensive: a dangling productionId (imported/hand-edited blob) must
    // degrade to the default production, not 500 the whole coverage read.
    let production: ProjectProduction;
    try {
      production = getProduction(projectData, s.productionId || undefined);
    } catch {
      production = ensureDefaultProduction(projectData);
    }
    const stale = !!event && (s.eventLinks || []).some((l: any) =>
      l.eventId === eventId && l.dramatizedAtEventUpdatedAt < event.updatedAt);
    const firstImage = (s.frames || []).find((f: any) => f.imageUrl)?.imageUrl || s.imageUrl;
    return {
      sceneId: s.id, sceneTitle: s.title,
      productionId: production.id, productionTitle: production.title, format: production.format,
      stale, imageUrl: firstImage,
    };
  });
  const comicPages: any[] = [];
  for (const production of projectData.productions || []) {
    for (const page of production.comicPages || []) {
      const scene = (projectData.interactions || []).find((s: any) => s.id === page.sceneId);
      if (scene && (scene.eventLinks || []).some((l: any) => l.eventId === eventId)) {
        comicPages.push({
          pageId: page.id, pageNumber: page.pageNumber, status: page.status,
          imageUrl: page.imageUrl, productionId: production.id, productionTitle: production.title,
        });
      }
    }
  }
  return { dramatizations, comicPages };
}

app.get('/api/narrative/events', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const events = (projectData.events || [])
      .slice()
      .sort((a, b) => a.chronologyIndex - b.chronologyIndex || a.id.localeCompare(b.id));
    res.json({ events });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.post('/api/narrative/events', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), title, description, entityIds, chronologyIndex, stateChanges, arcId, status, timelineId, sourceProductionId } = req.body || {};
    if (!title || typeof title !== 'string') return res.status(400).json({ error: 'title is required' });
    const projectData = loadProjectData(projectId);
    const events = ensureEvents(projectData);
    const now = new Date().toISOString();
    const event: WorldEvent = {
      id: mintId('evt'),
      chronologyIndex: Number.isFinite(Number(chronologyIndex)) ? Number(chronologyIndex) : nextChronologyIndex(projectData),
      title,
      description: typeof description === 'string' ? description : undefined,
      entityIds: Array.isArray(entityIds) ? entityIds.map(String) : [],
      stateChanges: Array.isArray(stateChanges) ? stateChanges : undefined,
      arcId: typeof arcId === 'string' ? arcId : undefined,
      timelineId: typeof timelineId === 'string' ? timelineId : undefined,
      status: status === 'canon' ? 'canon' : 'draft',
      sourceProductionId: typeof sourceProductionId === 'string' ? sourceProductionId : undefined,
      createdAt: now, updatedAt: now,
    };
    events.push(event);
    saveProjectData(projectId, projectData);
    res.json({ success: true, event });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.patch('/api/narrative/events/:id', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), ...updates } = req.body || {};
    const projectData = loadProjectData(projectId);
    const event = (projectData.events || []).find(e => e.id === req.params.id);
    if (!event) return res.status(404).json({ error: `Event not found: ${req.params.id}` });
    let dramatizableChange = false;
    if (typeof updates.title === 'string' && updates.title) { event.title = updates.title; dramatizableChange = true; }
    if (typeof updates.description === 'string') { event.description = updates.description; dramatizableChange = true; }
    if (Array.isArray(updates.entityIds)) { event.entityIds = updates.entityIds.map(String); dramatizableChange = true; }
    if (Array.isArray(updates.stateChanges)) { event.stateChanges = updates.stateChanges; dramatizableChange = true; }
    if (Number.isFinite(Number(updates.chronologyIndex))) event.chronologyIndex = Number(updates.chronologyIndex);
    if (typeof updates.arcId === 'string') event.arcId = updates.arcId || undefined;
    if (typeof updates.notes === 'string') event.notes = updates.notes; // author notes — not dramatizable content
    if (typeof updates.timelineId === 'string') event.timelineId = updates.timelineId || undefined;
    // C3 CANONIZATION GATE. Demotion to draft is a free, deliberate creator act;
    // promotion to canon MUST pass the gate + the temporal-conflict check, so we
    // route it through the shared canonizeEventCore — PATCH/update_event cannot
    // bypass canonization. On a block the core leaves status untouched and we
    // return 409 with the reason (+ resolutions) so the caller can act.
    let canonBlock: any = null;
    if (updates.status === 'draft' && event.status === 'canon') {
      event.status = 'draft';
      event.canonizedAt = undefined;
      event.canonizedBy = undefined;
    } else if (updates.status === 'canon' && event.status !== 'canon') {
      const result = canonizeEventCore(projectData, event, { force: updates.force === true, actor: 'creator' });
      if (!result.ok) canonBlock = result.block;
    }
    // Staleness reads updatedAt — bump it ONLY when the event's CONTENT
    // changed. Repositioning in the chronology (or arc/status bookkeeping)
    // changes nothing a scene depicts; a blanket bump would false-flag every
    // dramatization across every production.
    if (dramatizableChange) event.updatedAt = new Date().toISOString();
    saveProjectData(projectId, projectData);
    // The field edits DID land (success:true); the canon flip is reported
    // separately in canonBlocked so a caller can't misread a 409 as "nothing
    // changed" while the edits silently persisted. Pure canonization goes
    // through POST /events/:id/canonize (a clean 409 there).
    if (canonBlock) return res.json({ success: true, event, canonBlocked: canonBlock });
    res.json({ success: true, event });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// ============================================================================
// C3 — CANONIZATION: the gated, validated draft→canon status flip.
// Locking into canon is a REVIEWED status flip (not a merge — event-aware
// merge is C4/T4). Two checks gate the flip: (1) the telling's GATE
// (creator|vote|rule — pluggable so M2/M3 slot in), and (2) TEMPORAL CONSISTENCY
// (would making this event canon contradict the existing canon fold?). This is
// the "branch a comic off mid-movie, conflict resolution guaranteeing it can't
// contradict the movie" guarantee, built on C1.5's validateTemporalConsistency.
// ============================================================================

type CanonGate = 'creator' | 'vote' | 'rule';

/** The four narrative resolutions for a canon conflict (CHRONICLE_DESIGN).
 *  Advisory — the creator acts via the normal event tools. */
const CANON_RESOLUTIONS = [
  { kind: 'amend', label: 'Amend the draft', how: 'Edit this event (cast, stateChanges, or chronologyIndex) so it no longer contradicts canon.' },
  { kind: 'retcon', label: 'Retcon canon', how: 'Change the conflicting CANON event (e.g. move a death later) — a deliberate canon edit.' },
  { kind: 'bridge', label: 'Author a bridging event', how: 'Insert an event between them that reconciles the timeline (a rebirth, a reveal the death was staged).' },
  { kind: 'fork', label: 'Fork the timeline', how: 'Give this telling its own universe fork (set the event timelineId) so it need not agree with the canon timeline.' },
] as const;

/** Evaluate a telling's canon gate for one event. creator = always (a human is
 *  locking it); vote = quorum on canonVotes (M3 scaffold); rule = Aureum
 *  predicate (T6 scaffold — defers to creator override). */
function evaluateCanonGate(gate: CanonGate, ctx: { production?: ProjectProduction; event: WorldEvent }): { approved: boolean; gate: CanonGate; reason: string } {
  const { production, event } = ctx;
  switch (gate) {
    case 'vote': {
      const quorum = Math.max(1, production?.canonQuorum ?? 1);
      const votes = (event.canonVotes || []).length;
      return votes >= quorum
        ? { approved: true, gate, reason: `${votes}/${quorum} votes` }
        : { approved: false, gate, reason: `vote gate: ${votes}/${quorum} votes so far — needs ${quorum - votes} more. (M3 wires the ballot; a creator can override.)` };
    }
    case 'rule':
      return { approved: false, gate, reason: 'rule gate: no Aureum rule engine yet (T6). Switch this telling to the creator gate, or a creator can override.' };
    case 'creator':
    default:
      return { approved: true, gate: 'creator', reason: 'creator lock' };
  }
}

function violationKey(v: { eventId: string; entityId: string; code: string }): string {
  return `${v.eventId}|${v.entityId}|${v.code}`;
}

/** Canonize ONE event in place. On success mutates event (status/canonizedAt/
 *  canonizedBy) and returns {ok:true}; on a block leaves it untouched and
 *  returns {ok:false, block}. Does NOT persist — the caller saves. `force`
 *  overrides both the gate and a temporal conflict (a deliberate creator act,
 *  recorded in canonizedBy). */
function canonizeEventCore(
  projectData: ProjectData,
  event: WorldEvent,
  opts: { force?: boolean; actor?: string } = {},
): { ok: true; event: WorldEvent; already?: boolean; forced?: boolean } | { ok: false; block: any } {
  const { force = false, actor = 'creator' } = opts;
  if (event.status === 'canon') return { ok: true, event, already: true };

  // (1) GATE — how THIS telling's events reach canon. Only a production-born
  // event is bound to a telling's gate; a WORLD-authored event (no source)
  // uses the world default (creator) — NOT whatever production is active
  // (getProduction(undefined) would fall back to the active/default telling).
  let production: ProjectProduction | undefined;
  if (event.sourceProductionId) {
    try { production = getProduction(projectData, event.sourceProductionId); }
    catch { production = undefined; } // orphaned source (production deleted) → default creator gate
  }
  const gate: CanonGate = production?.canonGate || 'creator';
  const gateResult = evaluateCanonGate(gate, { production, event });
  if (!gateResult.approved && !force) {
    return { ok: false, block: { reason: 'gate', gate, message: gateResult.reason } };
  }

  // (2) TEMPORAL CONFLICT — would flipping THIS event to canon introduce a
  // contradiction that isn't already present in the canon fold? Diff the
  // canon-only violations before vs. after the simulated flip; only NEW ones
  // (caused/exposed by this flip) block. SCOPE the fold to the event's OWN
  // timeline (validateTemporalConsistency filters by timelineId; without it a
  // forked event is dropped from BOTH folds → the check would silently no-op,
  // exactly when "fork the timeline" was the escape hatch we recommended).
  const events = projectData.events || [];
  const foldOpts = { timelineId: event.timelineId, canonOnly: true } as const;
  const baseline = new Set(validateTemporalConsistency({ events } as any, foldOpts).map(violationKey));
  const prevStatus = event.status;
  event.status = 'canon';
  const introduced = validateTemporalConsistency({ events } as any, foldOpts).filter((v) => !baseline.has(violationKey(v)));
  if (introduced.length > 0 && !force) {
    event.status = prevStatus; // revert the simulation — nothing persists
    return {
      ok: false,
      block: {
        reason: 'conflict',
        violations: introduced,
        resolutions: CANON_RESOLUTIONS,
        message: `Canonizing "${event.title}" would contradict canon: ${introduced.map((v) => v.message).join(' ')}`,
      },
    };
  }

  // Commit the flip (status is already 'canon' from the simulation).
  const gateNote = gateResult.approved ? (gate === 'creator' ? 'creator' : `${gate}: ${gateResult.reason}`) : `${gate} (creator override)`;
  event.canonizedAt = new Date().toISOString();
  event.canonizedBy = force && introduced.length > 0 ? `${gateNote}, conflict overridden` : gateNote;
  return { ok: true, event, forced: force && introduced.length > 0 };
}

/** Canonize a whole telling: every DRAFT event this production birthed, in
 *  chronology order (so earlier events are canon before later ones are
 *  checked against them). Non-atomic by design — clean events lock, blocked
 *  ones stay draft with their reason. dryRun computes the outcome without
 *  persisting the flips. */
function canonizeProductionCore(
  projectData: ProjectData,
  productionId: string,
  opts: { force?: boolean; dryRun?: boolean } = {},
): { production: { id: string; title: string; canonGate: CanonGate }; canonized: Array<{ eventId: string; title: string }>; blocked: Array<{ eventId: string; title: string; reason: string; message: string; violations?: any[] }>; total: number } {
  const { force = false, dryRun = false } = opts;
  const production = getProduction(projectData, productionId);
  const events = projectData.events || [];
  const drafts = events
    .filter((e) => e.status === 'draft' && (e.sourceProductionId || DEFAULT_PRODUCTION_ID) === production.id)
    .slice()
    .sort((a, b) => a.chronologyIndex - b.chronologyIndex || a.id.localeCompare(b.id));

  const canonized: Array<{ eventId: string; title: string }> = [];
  const blocked: Array<{ eventId: string; title: string; reason: string; message: string; violations?: any[] }> = [];
  for (const e of drafts) {
    const result = canonizeEventCore(projectData, e, { force, actor: 'creator' });
    if (result.ok) canonized.push({ eventId: e.id, title: e.title });
    else blocked.push({ eventId: e.id, title: e.title, reason: result.block.reason, message: result.block.message, violations: result.block.violations });
  }
  if (dryRun) {
    // Undo the flips the core applied while probing.
    for (const c of canonized) {
      const e = events.find((x) => x.id === c.eventId);
      if (e) { e.status = 'draft'; e.canonizedAt = undefined; e.canonizedBy = undefined; }
    }
  }
  return { production: { id: production.id, title: production.title, canonGate: production.canonGate || 'creator' }, canonized, blocked, total: drafts.length };
}

/** Lock ONE event into canon (gated + validated). 409 on block (gate not met /
 *  temporal conflict) with the reason and resolution options. */
app.post('/api/narrative/events/:id/canonize', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), force, actor } = req.body || {};
    const projectData = loadProjectData(projectId);
    const event = (projectData.events || []).find((e) => e.id === req.params.id);
    if (!event) return res.status(404).json({ error: `Event not found: ${req.params.id}` });
    const result = canonizeEventCore(projectData, event, { force: force === true, actor: typeof actor === 'string' ? actor : 'creator' });
    if (!result.ok) return res.status(409).json({ success: false, error: result.block.message, ...result.block, event });
    saveProjectData(projectId, projectData);
    res.json({ success: true, event, canonizedBy: event.canonizedBy, forced: (result as any).forced === true });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** Return a canon event to draft — a deliberate creator act (un-publish). */
app.post('/api/narrative/events/:id/uncanonize', (req, res) => {
  try {
    const { projectId = getActiveProjectId() } = req.body || {};
    const projectData = loadProjectData(projectId);
    const event = (projectData.events || []).find((e) => e.id === req.params.id);
    if (!event) return res.status(404).json({ error: `Event not found: ${req.params.id}` });
    event.status = 'draft';
    event.canonizedAt = undefined;
    event.canonizedBy = undefined;
    saveProjectData(projectId, projectData);
    res.json({ success: true, event });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** Canonize a whole telling (lock the movie/comic). ?dryRun previews without
 *  flipping. Non-atomic: clean events lock; conflicting ones stay draft. */
app.post('/api/narrative/productions/:id/canonize', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), force, dryRun } = req.body || {};
    const projectData = loadProjectData(projectId);
    if (req.params.id !== DEFAULT_PRODUCTION_ID && !(projectData.productions || []).some((p) => p.id === req.params.id)) {
      return res.status(404).json({ error: `Unknown production: ${req.params.id}` });
    }
    const result = canonizeProductionCore(projectData, req.params.id, { force: force === true, dryRun: dryRun === true });
    if (dryRun !== true) saveProjectData(projectId, projectData);
    res.json({ success: true, dryRun: dryRun === true, ...result });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** Set a telling's canonization gate (creator|vote|rule) + optional vote quorum. */
app.post('/api/narrative/productions/:id/canon-gate', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), gate, quorum } = req.body || {};
    if (!['creator', 'vote', 'rule'].includes(gate)) return res.status(400).json({ error: "gate must be 'creator' | 'vote' | 'rule'" });
    const projectData = loadProjectData(projectId);
    if (req.params.id !== DEFAULT_PRODUCTION_ID && !(projectData.productions || []).some((p) => p.id === req.params.id)) {
      return res.status(404).json({ error: `Unknown production: ${req.params.id}` });
    }
    const production = getProduction(projectData, req.params.id);
    production.canonGate = gate as CanonGate;
    if (Number.isFinite(Number(quorum))) production.canonQuorum = Math.max(1, Number(quorum));
    saveProjectData(projectId, projectData);
    res.json({ success: true, production: { id: production.id, title: production.title, canonGate: production.canonGate, canonQuorum: production.canonQuorum } });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.post('/api/narrative/events/:id/link-scene', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), sceneId } = req.body || {};
    if (!sceneId) return res.status(400).json({ error: 'sceneId is required' });
    const projectData = loadProjectData(projectId);
    const event = (projectData.events || []).find(e => e.id === req.params.id);
    if (!event) return res.status(404).json({ error: `Event not found: ${req.params.id}` });
    const scene = (projectData.interactions || []).find((s: any) => s.id === sceneId);
    if (!scene) return res.status(404).json({ error: `Scene not found: ${sceneId}` });
    linkSceneToEvent(scene, event);
    scene.updatedAt = new Date().toISOString();
    saveProjectData(projectId, projectData);
    res.json({ success: true, sceneId, eventId: event.id, eventLinks: scene.eventLinks });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** Promote a scene into the event it dramatizes, in one atomic act: mints
 *  the event seeded from the scene (title, cast, source production) and
 *  links it with provenance. The two-way-media on-ramp. */
app.post('/api/narrative/events/from-scene', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), sceneId, title, chronologyIndex, stateChanges } = req.body || {};
    if (!sceneId) return res.status(400).json({ error: 'sceneId is required' });
    const projectData = loadProjectData(projectId);
    const scene = (projectData.interactions || []).find((s: any) => s.id === sceneId);
    if (!scene) return res.status(404).json({ error: `Scene not found: ${sceneId}` });
    const events = ensureEvents(projectData);
    const now = new Date().toISOString();
    const event: WorldEvent = {
      id: mintId('evt'),
      chronologyIndex: Number.isFinite(Number(chronologyIndex)) ? Number(chronologyIndex) : nextChronologyIndex(projectData),
      title: (typeof title === 'string' && title) || scene.title || 'Untitled event',
      description: scene.summary || scene.description || undefined,
      entityIds: (scene.participantIds || scene.participants || []).filter((p: any) => typeof p === 'string'),
      stateChanges: Array.isArray(stateChanges) ? stateChanges : undefined,
      status: 'draft',
      sourceProductionId: scene.productionId || DEFAULT_PRODUCTION_ID,
      createdAt: now, updatedAt: now,
    };
    events.push(event);
    linkSceneToEvent(scene, event);
    scene.updatedAt = now;
    saveProjectData(projectId, projectData);
    res.json({ success: true, event, sceneId });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** Two draft events describe the same moment → one survivor; links repoint.
 *  The cross-production reconciliation the design demands (product-1). */
app.post('/api/narrative/events/merge', (req, res) => {
  try {
    const { projectId = getActiveProjectId(), survivorId, mergedId } = req.body || {};
    if (!survivorId || !mergedId || survivorId === mergedId) return res.status(400).json({ error: 'survivorId and mergedId (distinct) are required' });
    const projectData = loadProjectData(projectId);
    const survivor = (projectData.events || []).find(e => e.id === survivorId);
    const merged = (projectData.events || []).find(e => e.id === mergedId);
    if (!survivor || !merged) return res.status(404).json({ error: 'Both events must exist' });
    // DRAFT-only reconciliation (the tool's contract): merging would silently
    // destroy a canon event — the C3 gate / C4 event-aware merge own that.
    if (survivor.status === 'canon' || merged.status === 'canon') {
      return res.status(400).json({ error: 'Cannot merge canon events — merge is draft-only reconciliation. Flip status deliberately or wait for event-aware merge (C4).' });
    }
    // Union the involvement; keep the survivor's chronology + text.
    survivor.entityIds = Array.from(new Set([...(survivor.entityIds || []), ...(merged.entityIds || [])]));
    if (merged.stateChanges?.length) survivor.stateChanges = [...(survivor.stateChanges || []), ...merged.stateChanges];
    survivor.updatedAt = new Date().toISOString();
    let repointed = 0;
    for (const scene of projectData.interactions || []) {
      for (const link of scene.eventLinks || []) {
        if (link.eventId === mergedId) {
          // Repoint the id ONLY — keep the old provenance so the scene reads
          // STALE against the survivor's changed content (fresh-stamping it
          // would mark the scene most in need of reconciliation as current).
          link.eventId = survivorId;
          repointed++;
        }
      }
    }
    projectData.events = (projectData.events || []).filter(e => e.id !== mergedId);
    saveProjectData(projectId, projectData);
    res.json({ success: true, survivor, linksRepointed: repointed });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** Draft-only deletion (canon events are protected — retraction of canon is
 *  a C4/narrative concern, not a DELETE). Scene links to the deleted draft
 *  are removed. */
app.delete('/api/narrative/events/:id', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const event = (projectData.events || []).find(e => e.id === req.params.id);
    if (!event) return res.status(404).json({ error: `Event not found: ${req.params.id}` });
    if (event.status === 'canon') return res.status(400).json({ error: 'Canon events cannot be deleted — demote to draft first (a deliberate act).' });
    projectData.events = (projectData.events || []).filter(e => e.id !== req.params.id);
    let unlinked = 0;
    for (const scene of projectData.interactions || []) {
      const before = (scene.eventLinks || []).length;
      if (before > 0) {
        scene.eventLinks = scene.eventLinks.filter((l: any) => l.eventId !== req.params.id);
        unlinked += before - scene.eventLinks.length;
      }
    }
    saveProjectData(projectId, projectData);
    res.json({ success: true, deleted: req.params.id, linksRemoved: unlinked });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * C2: the Chronicle rail's single data call — the universe chronology plus
 * per-production coverage lanes, aggregated in one pass. Lanes span the
 * events a production's scenes LINK (never scene.chronologyIndex — design
 * substrate-4). Comic pages count as dramatizations via their scene.
 */
app.get('/api/narrative/chronicle', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    ensureDefaultProduction(projectData);
    const events = (projectData.events || [])
      .slice()
      .sort((a, b) => a.chronologyIndex - b.chronologyIndex || a.id.localeCompare(b.id));
    const eventById = new Map(events.map(e => [e.id, e]));

    // production → set of linked event ids (via its scenes; comic pages ride their scene)
    const linksByProduction = new Map<string, Set<string>>();
    const touch = (productionId: string, eventId: string) => {
      if (!eventById.has(eventId)) return;
      if (!linksByProduction.has(productionId)) linksByProduction.set(productionId, new Set());
      linksByProduction.get(productionId)!.add(eventId);
    };
    let unlinkedSceneCount = 0;
    for (const scene of projectData.interactions || []) {
      const links: any[] = scene.eventLinks || [];
      if (links.length === 0) { unlinkedSceneCount++; continue; }
      const owner = scene.productionId || DEFAULT_PRODUCTION_ID;
      for (const l of links) touch(owner, l.eventId);
    }
    for (const production of projectData.productions || []) {
      for (const page of production.comicPages || []) {
        const scene = (projectData.interactions || []).find((s: any) => s.id === page.sceneId);
        for (const l of scene?.eventLinks || []) touch(production.id, l.eventId);
      }
    }

    const lanes = (projectData.productions || []).map(p => {
      const ids = Array.from(linksByProduction.get(p.id) || []);
      const idxs = ids.map(id => eventById.get(id)!.chronologyIndex);
      const prodScenes = scenesFor(projectData, p.id);
      const renderedScenes = prodScenes.filter((sc: any) => (sc.frames || []).some((f: any) => f.imageUrl)).length;
      const keptPages = (p.comicPages || []).filter(pg => pg.status === 'kept').length;
      const draftEvents = events.filter(e => e.status === 'draft' && e.sourceProductionId === p.id).length;
      // Lightweight production STAGE, derived (no new authored field):
      // drafting → producing → exported. "Which threads are still in
      // production, and at what stage per media" (Michael).
      const exportedAt = (p as any).lastComicExport?.exportedAt
        || ((projectData as any).lastExport && p.id === DEFAULT_PRODUCTION_ID ? (projectData as any).lastExport.exportedAt : undefined);
      const stage = exportedAt ? 'exported'
        : (renderedScenes > 0 || (p.comicPages || []).length > 0) ? 'producing'
        : prodScenes.length > 0 ? 'drafting' : 'empty';
      // Content stills for the track lane (film: scene frame images in scene
      // order; comic: page images in page order) — the "each track shows
      // stills of its content" requirement. Tagged with the chronologyIndex
      // of the event the owning scene dramatizes (for playhead alignment).
      const thumbnails: Array<{ url: string; chronologyIndex: number | null; kind: string; label?: string }> = [];
      const sceneChron = (sc: any): number | null => {
        const link = (sc.eventLinks || [])[0];
        const evt = link ? eventById.get(link.eventId) : undefined;
        return evt ? evt.chronologyIndex : null;
      };
      if (p.format === 'comic') {
        for (const pg of (p.comicPages || []).filter(pg => pg.status !== 'rejected').sort((a, b) => a.pageNumber - b.pageNumber)) {
          if (!pg.imageUrl) continue;
          const sc = prodScenes.find((s: any) => s.id === pg.sceneId);
          thumbnails.push({ url: pg.imageUrl, chronologyIndex: sc ? sceneChron(sc) : null, kind: 'page', label: `p.${pg.pageNumber}` });
          if (thumbnails.length >= 24) break;
        }
      } else {
        for (const sc of prodScenes.slice().sort((a: any, b: any) => (a.position ?? 0) - (b.position ?? 0))) {
          const chron = sceneChron(sc);
          for (const f of (sc.frames || [])) {
            if (f.imageUrl) { thumbnails.push({ url: f.imageUrl, chronologyIndex: chron, kind: 'frame', label: sc.title }); break; }
          }
          if (thumbnails.length >= 24) break;
        }
      }
      // Participating entities (union across the production's scenes) — the
      // info-panel's "who's in this production".
      const entitySet = new Set<string>();
      for (const sc of prodScenes) for (const pid of (sc.participantIds || sc.participants || [])) if (typeof pid === 'string') entitySet.add(pid);
      return {
        productionId: p.id, title: p.title, format: p.format,
        eventIds: ids,
        minIndex: idxs.length ? Math.min(...idxs) : null,
        maxIndex: idxs.length ? Math.max(...idxs) : null,
        sceneCount: prodScenes.length,
        renderedScenes,
        keptPages,
        draftEvents,
        stage,
        autonomy: p.autonomy || 'direct',
        // C3: how this telling's draft events reach canon.
        canonGate: p.canonGate || 'creator',
        // A production is a BRANCH until its events are canon (draft events
        // present) — else it's part of main. The visual branch/main split.
        branchState: draftEvents > 0 ? 'branch' : 'main',
        thumbnails,
        entityIds: Array.from(entitySet),
        notes: (p as any).notes || undefined,
      };
    });

    const arcs = (projectData.arcs || []).map(a => {
      const idxs = events.filter(e => e.arcId === a.id).map(e => e.chronologyIndex);
      return { id: a.id, title: a.title, status: a.status, minIndex: idxs.length ? Math.min(...idxs) : null, maxIndex: idxs.length ? Math.max(...idxs) : null };
    });

    // Minimal cross-production scene list for the World view's link picker.
    const scenePicker = (projectData.interactions || []).map((sc: any) => ({
      id: sc.id, title: sc.title || 'Untitled', productionId: sc.productionId || DEFAULT_PRODUCTION_ID,
      linked: (sc.eventLinks || []).length > 0,
    }));
    res.json({ events, lanes, arcs, unlinkedSceneCount, scenePicker });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

app.get('/api/narrative/events/:id/coverage', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const event = (projectData.events || []).find(e => e.id === req.params.id);
    if (!event) return res.status(404).json({ error: `Event not found: ${req.params.id}` });
    res.json({ event, ...getEventCoverage(projectData, event.id) });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** C1.5: fold-forward temporal validation of the whole chronology. */
app.get('/api/narrative/chronology/validate', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const violations = validateTemporalConsistency({ events: projectData.events || [] } as any, { canonOnly: req.query.canonOnly === '1' });
    res.json({ violations, count: violations.length });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/** C1.5: the world as it stood at story-moment t (the fold, not a checkout). */
app.get('/api/narrative/chronology/state-at', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const t = Number(req.query.t);
    if (!Number.isFinite(t)) return res.status(400).json({ error: 't (chronologyIndex) is required' });
    const projectData = loadProjectData(projectId);
    const states = worldStateAt({ events: projectData.events || [] } as any, t, {
      canonOnly: req.query.canonOnly !== '0',
      timelineId: (req.query.timelineId as string) || undefined,
    });
    const entities = Array.from(states.values()).map(st => ({
      ...st,
      name: (projectData.entities || []).find((e: any) => e.id === st.entityId)?.name || st.entityId,
    }));
    res.json({ t, entities });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

