// ============================================================================
// T1-COMIC — THE COMIC RENDERER (TRANSMEDIA_ROADMAP T1 / REVIEW §9.4)
// Whole-page generation is PRIMARY (NB2 renders lettering in-image — the
// approach that produced the good consistent comics in the g89le pipeline);
// the composer/SVG path remains the repair fallback. Every page render goes
// through /render (style pins + graph refs — no G5 bypass). Pages are HITL:
// draft → keep/reject/redo; export = PDF of the kept pages.
// ============================================================================

type ComicJob = {
  id: string;
  projectId: string;
  productionId: string;
  status: 'pending' | 'processing' | 'done' | 'error';
  pagesTotal: number;
  pagesDone: number;
  pageIds: string[];
  currentSceneId?: string;
  error?: string;
  startedAt: number;
  updatedAt: number;
  completedAt?: number;
};
const comicJobs = createJobStore<ComicJob>('comic', {
  dir: JOBS_DIR,
  terminalStates: ['done', 'error'],
  failureState: 'error',
});

/** Panel-by-panel page brief from a scene's frames (the microdrama page-brief
 *  pattern, ported as prompting). Falls back to a splash page for frameless
 *  scenes. */
function buildComicPageBrief(scene: any, frames: any[], pageNumber: number, totalPages: number, partLabel?: string): string {
  const lines: string[] = [];
  lines.push(`COMIC BOOK PAGE ${pageNumber} of ${totalPages} — one complete comic page, portrait, full-page layout.`);
  lines.push(`Scene: "${scene.title || 'Untitled'}"${partLabel ? ` (${partLabel})` : ''}${scene.summary ? ` — ${scene.summary}` : ''}`);
  if (frames.length === 0) {
    lines.push(`SPLASH PAGE (single full-page panel): ${scene.prose?.slice(0, 600) || scene.description || scene.title}`);
  } else {
    lines.push(`${frames.length} panels with clean gutters, professional comic composition (vary panel sizes for drama).`);
    frames.forEach((f: any, i: number) => {
      const beat = f.visualBeat || f.visual_beat || f.description || f.title || 'continuation beat';
      const parts = [`PANEL ${i + 1}: ${beat}.`];
      const present = (f.participantRefs || []).map((pr: any) => pr?.name).filter(Boolean);
      if (present.length > 0) parts.push(`Characters in this panel: ${present.join(', ')}.`);
      if (f.shotType || f.camera) parts.push(`Framing: ${[f.shotType, f.camera].filter(Boolean).join(', ')}.`);
      const dialogue: string[] = Array.isArray(f.dialogue) ? f.dialogue : (f.dialogue ? [String(f.dialogue)] : []);
      for (const d of dialogue) {
        // House convention: "Name: line" — letter ONLY the line inside the
        // balloon; the speaker drives the tail (never print "NAME:" in-balloon).
        const m = /^([A-Za-z][\w .'’-]{0,30}):\s*(.+)$/.exec(String(d));
        if (m) parts.push(`Speech balloon spoken by ${m[1]} (aim the balloon tail at ${m[1]}; do NOT letter the name prefix): "${m[2]}"`);
        else parts.push(`Speech balloon: "${d}"`);
      }
      if (f.caption) parts.push(`Caption box: "${f.caption}"`);
      const sfx: string[] = Array.isArray(f.sfx) ? f.sfx : (f.sfx ? [String(f.sfx)] : []);
      for (const s of sfx) parts.push(`SFX lettering: ${s}`);
      lines.push(parts.join(' '));
    });
  }
  lines.push('LETTERING: render all dialogue EXACTLY as written, inside speech balloons with tails pointing at the speaker; captions in rectangular caption boxes; SFX as stylized onomatopoeia integrated into the art. Spell every word correctly.');
  lines.push('CHARACTER CONSISTENCY: the attached character reference images define each character\'s exact appearance — reproduce faces, hair, and clothing faithfully in every panel.');
  lines.push('No page numbers, no watermarks, no artist signature, no borders outside the page.');
  return lines.join('\n');
}

/** Identity-bound references (the g89le page-room discipline): each ref
 *  carries the entity's NAME + a short appearance description so the prompt
 *  can bind attached images to named characters by number. Characters first
 *  (castLooks-aware), then the scene's location; cap 5 (the prior page and
 *  style pins ride separately). */
type ComicRef = { url: string; name: string; appearance?: string; kind: 'character' | 'location' | 'object' };

/** Fuzzy entity-by-name resolution (the g89le room's matcher): exact →
 *  case-insensitive → first-word partial ("Ru" → "Ru (Rubisco)"). */
function resolveComicEntityByName(projectData: ProjectData, name: string): any | undefined {
  const entities = projectData.entities || [];
  const n = String(name).trim().toLowerCase();
  if (!n) return undefined;
  return entities.find((e: any) => (e.name || '').toLowerCase() === n)
    || entities.find((e: any) => (e.name || '').toLowerCase().split(/[\s(]/)[0] === n.split(/[\s(]/)[0]);
}

/**
 * PAGE-LEVEL entity references (the full g89le discipline): who/what is
 * actually IN these panels, not just the scene's cast list. Signals, in
 * priority order:
 *   1. frame participants (participantIds + participantRefs names)
 *   2. dialogue speakers ("Name: line")
 *   3. known entity names appearing in panel beats/descriptions
 *   4. the scene's location (+ location named per-frame)
 *   5. significant OBJECTS (object/artifact/prop-typed entities named in
 *      beats — the memory vial, the lantern)
 * Characters keep priority (multi-character pages are where likeness drift
 * hurts most); scene participants seed the list so a page never loses its
 * leads. Cap 6 (prior page + style pins ride separately).
 */
function collectComicRefs(projectData: ProjectData, scene: any, frames: any[] = [], cap: number = 6): ComicRef[] {
  const characters: any[] = [];
  const locations: any[] = [];
  const objects: any[] = [];
  const seenEntity = new Set<string>();
  const OBJECT_TYPES = ['object', 'artifact', 'prop', 'item'];
  const LOCATION_TYPES = ['location', 'place', 'setting'];
  const classify = (entity: any) => {
    if (!entity || seenEntity.has(entity.id)) return;
    seenEntity.add(entity.id);
    const t = String(entity.type || '').toLowerCase();
    if (LOCATION_TYPES.includes(t)) locations.push(entity);
    else if (OBJECT_TYPES.includes(t)) objects.push(entity);
    else characters.push(entity);
  };

  // 1. Scene cast seeds the leads; then frame-level participants.
  for (const pid of (scene.participantIds || scene.participants || []).filter((p: any) => typeof p === 'string')) {
    classify((projectData.entities || []).find((e: any) => e.id === pid || e.name === pid));
  }
  for (const f of frames) {
    for (const pid of (f.participantIds || []).filter((p: any) => typeof p === 'string')) {
      classify((projectData.entities || []).find((e: any) => e.id === pid || e.name === pid));
    }
    for (const pr of (f.participantRefs || [])) {
      if (pr?.entityId) classify((projectData.entities || []).find((e: any) => e.id === pr.entityId));
      else if (pr?.name) classify(resolveComicEntityByName(projectData, pr.name));
    }
    // 2. Dialogue speakers.
    const dialogue: string[] = Array.isArray(f.dialogue) ? f.dialogue : (f.dialogue ? [String(f.dialogue)] : []);
    for (const d of dialogue) {
      const m = /^([A-Za-z][\w .'’-]{0,30}):\s*/.exec(String(d));
      if (m) classify(resolveComicEntityByName(projectData, m[1]));
    }
    // 3+5. Known entity names in the beat text (characters AND objects AND locations).
    const beat = `${f.visualBeat || f.visual_beat || ''} ${f.description || ''} ${f.title || ''}`.toLowerCase();
    if (beat.trim()) {
      for (const entity of projectData.entities || []) {
        if (seenEntity.has(entity.id)) continue;
        const first = (entity.name || '').toLowerCase().split(/[\s(]/)[0];
        if (first && first.length > 2 && beat.includes(first)) classify(entity);
      }
    }
    // 4. Per-frame location.
    if (f.locationId) classify((projectData.entities || []).find((e: any) => e.id === f.locationId));
  }
  const locId = scene.locationId || scene.location;
  if (locId) classify((projectData.entities || []).find((e: any) => e.id === locId || e.name === locId));

  // Assemble by priority: characters → first location → objects.
  const refs: ComicRef[] = [];
  const seenUrl = new Set<string>();
  const push = (entity: any, kind: ComicRef['kind']) => {
    if (refs.length >= cap) return;
    const lookLabel = scene.castLooks?.[entity.id] || scene.castLooks?.[entity.name];
    let url: string | undefined;
    if (lookLabel && Array.isArray(entity.imageGallery)) {
      const match = entity.imageGallery.find((g: any) => (g.label || '').toLowerCase() === String(lookLabel).toLowerCase());
      url = match?.url;
    }
    url = url || entity.referenceImage || entity.imageUrl;
    if (!url || seenUrl.has(url)) return;
    seenUrl.add(url);
    refs.push({ url, name: entity.name || entity.id, appearance: (entity.appearance || entity.description || '').slice(0, 200) || undefined, kind });
  };
  for (const c of characters) push(c, 'character');
  for (const l of locations.slice(0, 1)) push(l, 'location');
  for (const o of objects) push(o, 'object');
  return refs;
}

/** The comic craft doctrine (ported from g89le agents/skills/comic_visual.md
 *  — the iterated ruleset behind their good pages). */
const COMIC_CRAFT_RULES = [
  'COMIC CRAFT RULES:',
  '- Visual-first: if the art can SHOW it, no dialogue for it. Expressions carry emotion; action panels are nearly wordless.',
  '- Each panel freezes the single most dramatic instant. Vary camera angles and shot types — no repeated talking-head mediums.',
  '- Panel size = pacing: small panels fast, large panels slow and impactful.',
  '- The LAST panel must pull the reader toward the next page.',
  '- Reading flow is Z-pattern (left-to-right, top-to-bottom); the layout must guide the eye.',
  '- Max 25 words per speech balloon; max 2-3 balloons per panel.',
  '- Captions add what art cannot show (inner thought, time jumps). SFX are bold lettering INTEGRATED into the art.',
].join('\n');

/** Numbered identity block binding each attached reference image to a named
 *  character/location with its appearance (g89le room_orchestrator pattern —
 *  anonymous refs are how likeness drift happens). */
function buildConsistencyBlock(refs: ComicRef[]): string {
  if (refs.length === 0) return '';
  const KIND_LABEL = { character: '', location: ' (the LOCATION — match its architecture/geography)', object: ' (a significant OBJECT — match its design exactly)' } as const;
  const lines = refs.map((r, i) =>
    `- Reference image ${i + 1} is **${r.name}**${KIND_LABEL[r.kind] || ''}${r.appearance ? `: ${r.appearance}` : ''}`);
  return [
    'ENTITY CONSISTENCY (CRITICAL — match reference images EXACTLY):',
    ...lines,
    'Each character MUST look identical to their reference image across EVERY panel they appear in on this page — same face, skin tone, hair style, clothing, and build, from every angle. In multi-character panels keep each person unmistakably distinct; never blend or swap features between characters.',
  ].join('\n');
}

/** The g89le "page_producer" pass: one fast LLM call turns the mechanical
 *  brief + cast identity into a comprehensive generation prompt — layout,
 *  per-panel action, exact balloon text, captions, SFX, camera, character
 *  positions, backgrounds, lighting, mood. THE prompting-quality step the
 *  original pipeline iterated hardest on. Falls back to the mechanical brief. */
async function producePageGenerationPrompt(brief: string, refs: ComicRef[], styleHint: string): Promise<string | null> {
  if (!llmAdapter) return null;
  try {
    const castCtx = refs.length > 0
      ? `## Cast on this page\n${refs.map(r => `- **${r.name}**${r.appearance ? `: ${r.appearance}` : ''}`).join('\n')}\n\n`
      : '';
    const producerPrompt =
      `${castCtx}## Page outline\n${brief}\n\n` +
      `Create a detailed production brief for this comic page: a comprehensive generation prompt with ALL details needed to generate a complete comic book page as a single image — panel layout (sizes and arrangement), per-panel action, exact dialogue text in speech balloons, caption text, sound effects, camera angles, character positions within each panel, backgrounds, lighting, and mood. Detailed enough that an image generator produces a finished, publication-ready page.${styleHint ? ` Art style: ${styleHint}.` : ''}\n\n` +
      `CRITICAL — DIALOGUE IN SPEECH BUBBLES:\n` +
      `- Speech bubbles must contain ONLY the spoken words — NO character names\n` +
      `- WRONG: 'Dragon: "Fall back!"'\n` +
      `- CORRECT: '"Fall back!"' (with the balloon tail pointing at the speaker)\n\n` +
      COMIC_CRAFT_RULES;
    const result = await llmAdapter.generateStructuredOutput(
      producerPrompt,
      z.object({ generationPrompt: z.string() }),
      { temperature: 0.7, maxTokens: 4000, modelPreference: 'fast' },
    );
    return result?.generationPrompt || null;
  } catch (err: any) {
    console.warn('page producer pass failed (using mechanical brief):', err?.message);
    return null;
  }
}

const COMIC_ASPECTS = ['2:3', '3:4', '9:16', '1:1'];

async function renderComicPage(
  projectId: string,
  prompt: string,
  referenceUrls: string[],
  aspectRatio?: string,
  productionId?: string,
): Promise<{ imageUrl: string; actualPromptSent?: string }> {
  const aspect = COMIC_ASPECTS.includes(aspectRatio || '') ? aspectRatio : '2:3';
  const resp = await fetch(`http://localhost:${PORT}/api/narrative/visual/render`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    // productionId → the render resolves THIS production's selected style.
    body: JSON.stringify({ projectId, prompt, referenceUrls, aspectRatio: aspect, productionId }),
  });
  if (!resp.ok) throw new Error(`page render failed: ${await resp.text()}`);
  const data = await resp.json();
  if (!data.imageUrl) throw new Error('page render returned no imageUrl');
  return { imageUrl: data.imageUrl, actualPromptSent: data.actualPromptSent };
}

const MAX_PANELS_PER_PAGE = 5;
type ComicPagePlan = { sceneId: string; frames: any[]; partLabel?: string };

/** One page per ≤5-frame chunk — long scenes SPLIT across pages instead of
 *  silently dropping panels (review craft-2). */
function planComicPages(scenes: any[]): ComicPagePlan[] {
  const plans: ComicPagePlan[] = [];
  for (const scene of scenes) {
    const frames: any[] = scene.frames || [];
    if (frames.length <= MAX_PANELS_PER_PAGE) {
      plans.push({ sceneId: scene.id, frames });
      continue;
    }
    const parts = Math.ceil(frames.length / MAX_PANELS_PER_PAGE);
    console.log(`📖 Scene "${scene.title}" has ${frames.length} shots → splitting across ${parts} pages`);
    for (let part = 0; part < parts; part++) {
      plans.push({
        sceneId: scene.id,
        frames: frames.slice(part * MAX_PANELS_PER_PAGE, (part + 1) * MAX_PANELS_PER_PAGE),
        partLabel: `part ${part + 1} of ${parts}`,
      });
    }
  }
  return plans;
}

async function runComicJob(jobId: string, params: { projectId: string; productionId: string; sceneIds: string[]; aspectRatio?: string }): Promise<void> {
  const job = comicJobs.get(jobId);
  if (!job) return;
  const { projectId, productionId } = params;
  try {
    job.status = 'processing';
    job.updatedAt = Date.now();
    {
      const projectData = loadProjectData(projectId);
      const scenes = params.sceneIds
        .map(id => (projectData.interactions || []).find((s: any) => s.id === id))
        .filter(Boolean);
      const plans = planComicPages(scenes);
      job.pagesTotal = plans.length;
      (job as any).plans = plans.map(pl => ({ sceneId: pl.sceneId, frameIds: pl.frames.map((f: any) => f.id), partLabel: pl.partLabel }));
    }
    const plans: Array<{ sceneId: string; frameIds: string[]; partLabel?: string }> = (job as any).plans;

    for (let i = 0; i < plans.length; i++) {
      // Re-resolve FRESH each iteration: the render awaits span minutes and
      // another request may have replaced the cache entry — mutating a stale
      // snapshot would clobber concurrent edits on save (review split-1).
      const projectData = loadProjectData(projectId);
      const production = getProduction(projectData, productionId);
      if (!production.comicPages) production.comicPages = [];
      // Stable numbering: max existing number + 1 — NEVER a live count, which
      // shrinks on reject and collides (review correctness-1/scoping-4).
      const pageNumber = Math.max(0, ...production.comicPages.map(p => p.pageNumber || 0)) + 1;
      const totalPages = pageNumber + (plans.length - 1 - i);
      const priorPageUrl: string | undefined = production.comicPages
        .slice().reverse().find(p => p.status !== 'rejected' && p.imageUrl)?.imageUrl;

      const scene = (projectData.interactions || []).find((s: any) => s.id === plans[i].sceneId);
      if (!scene) continue;
      const frames = (scene.frames || []).filter((f: any) => plans[i].frameIds.includes(f.id));
      job.currentSceneId = scene.id;
      job.updatedAt = Date.now();

      const brief = buildComicPageBrief(scene, frames, pageNumber, totalPages, plans[i].partLabel);
      const refs = collectComicRefs(projectData, scene, frames);

      // The g89le page-producer pass: LLM-author the rich generation prompt
      // (positions, lighting, mood, exact balloon text) from the outline.
      const styleHint = getEffectiveVisualStylePrompt(projectId) || '';
      const produced = await producePageGenerationPrompt(brief, refs, styleHint);
      let prompt = produced || `${brief}\n\n${COMIC_CRAFT_RULES}`;

      // Numbered identity binding FIRST (refs attach in this order).
      const consistency = buildConsistencyBlock(refs);
      if (consistency) prompt = `${consistency}\n\n${prompt}`;

      // Prior page rides LAST, style-ONLY (the iterated g89le wording —
      // naming it a content/continuity ref invited layout copying).
      const refUrls = refs.map(r => r.url);
      if (priorPageUrl) {
        refUrls.push(priorPageUrl);
        prompt += `\n\nSTYLE CONTINUITY: The LAST reference image is the previous page of this comic. Use it ONLY to match the art style, line weight, color grading, inking technique, and shading approach. Do NOT copy its panel layout, composition, or content — create a fresh, unique page layout for this new page.`;
      }
      const rendered = await renderComicPage(projectId, prompt, refUrls, params.aspectRatio, params.productionId);

      const page = {
        id: mintId('cpage'),
        pageNumber,
        sceneId: scene.id,
        brief,
        imageUrl: rendered.imageUrl,
        prompt: rendered.actualPromptSent,
        status: 'draft' as const,
        generatedAt: new Date().toISOString(),
      };
      production.comicPages.push(page);
      production.updatedAt = new Date().toISOString();
      saveProjectData(projectId, projectData);
      job.pageIds.push(page.id);
      job.pagesDone = job.pageIds.length; // honest count (review correctness-2)
      job.updatedAt = Date.now();
    }
    job.status = 'done';
    job.completedAt = Date.now();
    job.updatedAt = Date.now();
    console.log(`📖 Comic job ${jobId} done — ${job.pagesDone}/${job.pagesTotal} pages`);
    flushAllJobStores();
  } catch (err: any) {
    job.status = 'error';
    job.error = err?.message || String(err);
    job.updatedAt = Date.now();
    console.error(`📖 Comic job ${jobId} failed:`, job.error);
    flushAllJobStores();
  }
}

app.post('/api/narrative/comic/compose', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.body?.productionId as string | undefined);
    let sceneIds: string[] = Array.isArray(req.body?.sceneIds) ? req.body.sceneIds.map(String) : [];
    if (sceneIds.length === 0) {
      sceneIds = scenesFor(projectData, production.id)
        .slice()
        .sort((a: any, b: any) => (a.position ?? 0) - (b.position ?? 0))
        .map((s: any) => s.id);
    } else {
      // Explicit sceneIds are INTENT and may come from any production in the
      // world — "make a comic of my film" adapts the film's scenes into the
      // comic production (the scene itself never moves; the page references
      // it). Missing ids fail loudly; cross-production adaptation is
      // REPORTED (not silent, not blocked — review scoping-2's kernel).
      for (const id of sceneIds) {
        const scene = (projectData.interactions || []).find((s: any) => s.id === id);
        if (!scene) return res.status(400).json({ error: `Scene not found: ${id}` });
      }
    }
    const crossProduction = sceneIds.filter(id => {
      const scene = (projectData.interactions || []).find((s: any) => s.id === id);
      return scene && !sceneBelongsToProduction(scene, production);
    });
    if (sceneIds.length === 0) return res.status(400).json({ error: 'No scenes to compose — pass sceneIds or add scenes to the production.' });
    if (sceneIds.length > 20) return res.status(400).json({ error: `${sceneIds.length} scenes — cap is 20 pages per run.` });
    const jobId = mintId('comic');
    const job: ComicJob = {
      id: jobId, projectId, productionId: production.id, status: 'pending',
      pagesTotal: sceneIds.length, pagesDone: 0, pageIds: [],
      startedAt: Date.now(), updatedAt: Date.now(),
    };
    comicJobs.set(jobId, job);
    const aspectRatio = typeof req.body?.aspectRatio === 'string' ? req.body.aspectRatio : undefined;
    void runComicJob(jobId, { projectId, productionId: production.id, sceneIds, aspectRatio });
    res.json({ jobId, pagesTotal: sceneIds.length, productionId: production.id, ...(crossProduction.length > 0 ? { adaptingFromOtherProductions: crossProduction } : {}) });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

app.get('/api/narrative/comic/job/:jobId', (req, res) => {
  const job = comicJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Comic job not found' });
  res.json(job);
});

app.get('/api/narrative/comic/pages', (req, res) => {
  try {
    const projectId = (req.query.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.query.productionId as string | undefined);
    res.json({ productionId: production.id, pages: production.comicPages || [] });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

app.post('/api/narrative/comic/pages/:pageId/decide', (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const decision = req.body?.decision;
    if (!['keep', 'reject'].includes(decision)) return res.status(400).json({ error: "decision must be 'keep' or 'reject'" });
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.body?.productionId as string | undefined);
    const page = (production.comicPages || []).find(p => p.id === req.params.pageId);
    if (!page) return res.status(404).json({ error: `Page not found: ${req.params.pageId}` });
    page.status = decision === 'keep' ? 'kept' : 'rejected';
    page.updatedAt = new Date().toISOString();
    saveProjectData(projectId, projectData);
    res.json({ success: true, page });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

app.post('/api/narrative/comic/pages/:pageId/redo', async (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const feedback = typeof req.body?.feedback === 'string' ? req.body.feedback : '';
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.body?.productionId as string | undefined);
    const page = (production.comicPages || []).find(p => p.id === req.params.pageId);
    if (!page) return res.status(404).json({ error: `Page not found: ${req.params.pageId}` });
    const scene = (projectData.interactions || []).find((s: any) => s.id === page.sceneId);
    const refs = scene ? collectComicRefs(projectData, scene, scene.frames || []) : [];
    const baseBrief = feedback ? `${page.brief}\nREVISION NOTES (apply these changes): ${feedback}` : page.brief;
    const produced = await producePageGenerationPrompt(baseBrief, refs, getEffectiveVisualStylePrompt(projectId) || '');
    let prompt = produced || `${baseBrief}\n\n${COMIC_CRAFT_RULES}`;
    const consistency = buildConsistencyBlock(refs);
    if (consistency) prompt = `${consistency}\n\n${prompt}`;
    const rendered = await renderComicPage(projectId, prompt, refs.map(r => r.url), undefined, production.id);
    if (page.imageUrl) {
      page.takes = page.takes || [];
      page.takes.push({ imageUrl: page.imageUrl, prompt: page.prompt, generatedAt: page.generatedAt || new Date().toISOString() });
    }
    page.imageUrl = rendered.imageUrl;
    page.prompt = rendered.actualPromptSent;
    page.status = 'draft';
    page.generatedAt = new Date().toISOString();
    page.updatedAt = page.generatedAt;
    saveProjectData(projectId, projectData);
    res.json({ success: true, page });
  } catch (error: any) {
    res.status(String(error.message || '').startsWith('Unknown production') ? 400 : 500).json({ error: error.message });
  }
});

app.post('/api/narrative/comic/export', async (req, res) => {
  try {
    const projectId = (req.body?.projectId as string) || getActiveProjectId();
    const projectData = loadProjectData(projectId);
    const production = getProduction(projectData, req.body?.productionId as string | undefined);
    const pages = (production.comicPages || [])
      .filter(p => p.imageUrl && p.status !== 'rejected')
      .sort((a, b) => a.pageNumber - b.pageNumber);
    if (pages.length === 0) return res.status(400).json({ error: 'No non-rejected pages to export.' });

    const { PDFDocument } = await import('pdf-lib');
    const pdf = await PDFDocument.create();
    for (const page of pages) {
      const imgResp = await fetch(`http://localhost:${PORT}${page.imageUrl!.startsWith('/') ? '' : '/'}${page.imageUrl}`);
      if (!imgResp.ok) throw new Error(`could not read page image ${page.pageNumber}`);
      const bytes = new Uint8Array(await imgResp.arrayBuffer());
      let image;
      try {
        image = await pdf.embedPng(bytes);
      } catch {
        image = await pdf.embedJpg(bytes);
      }
      const pdfPage = pdf.addPage([image.width, image.height]);
      pdfPage.drawImage(image, { x: 0, y: 0, width: image.width, height: image.height });
    }
    const fileName = `comic_${production.id}_${mintFileSuffix()}.pdf`;
    if (!fs.existsSync(EXPORTS_DIR)) fs.mkdirSync(EXPORTS_DIR, { recursive: true });
    fs.writeFileSync(path.join(EXPORTS_DIR, fileName), await pdf.save());
    const url = `/api/narrative/visual/exports/${fileName}`;
    production.lastComicExport = { fileName, url, pageCount: pages.length, exportedAt: new Date().toISOString() };
    production.updatedAt = new Date().toISOString();
    saveProjectData(projectId, projectData);
    res.json({ success: true, url, fileName, pageCount: pages.length });
  } catch (error: any) {
    res.status(String(error.message || '').startsWith('Unknown production') ? 400 : 500).json({ error: error.message });
  }
});

